import "./PluginIconColor.css";

import { useSettings } from "@api/Settings";
import ErrorBoundary from "@components/ErrorBoundary";
import { getTestcordIconColor } from "@testcordplugins/TestcordHelper/iconColors";
import { Logger } from "@utils/Logger";
import { classes } from "@utils/misc";
import { find, findComponentByCodeLazy, findCssClassesLazy, findModuleId, wreq } from "@webpack";
import { Clickable, Tooltip, useEffect, useState } from "@webpack/common";
import type { ComponentType, CSSProperties, JSX, MouseEventHandler, ReactNode } from "react";

const logger = new Logger("HeaderBarAPI");

const HeaderBarClasses = findCssClassesLazy("clickable", "selected", "badge", "badgeContainer");
const ToolbarClasses = findCssClassesLazy("iconWrapper", "clickable");

function findDiscordHeaderBarIcon(): ComponentType<ChannelToolbarButtonProps> | null {
    const id = findModuleId("HEADER_BAR_BADGE_TOP");
    if (id) {
        const mod = wreq(id);
        if (mod) {
            for (const key of Object.keys(mod)) {
                const exp = mod[key];
                if (exp && typeof exp === "object" && typeof exp.render === "function") {
                    return exp;
                }
            }
        }
    }
    return find((m: any) => {
        if (!m || typeof m !== "object") return false;
        for (const k in m) {
            const exp = m[k];
            if (exp && typeof exp === "object" && typeof exp.render === "function") {
                const s = exp.render.toString();
                if (s.includes('"aria-haspopup":') && s.includes("tooltipSpacing")) {
                    return exp;
                }
            }
        }
        return false;
    });
}

// Equicord upstream now uses a direct findComponentByCodeLazy anchor — more resilient after minification.
// Testcord keeps its thorough fallback (findDiscordHeaderBarIcon) but prefers upstream's anchor to get new logic without breaking color handling.
// The fallback remains for resilience if Discord renames the anchor.
export const HeaderBarIcon: ComponentType<ChannelToolbarButtonProps> = findComponentByCodeLazy("tooltipPosition:", '"aria-haspopup":', '"data-jump-section":') as ComponentType<ChannelToolbarButtonProps>;
void findDiscordHeaderBarIcon;
const TESTCORD_TOP_BAR_ICON_COLOR_SETTING: ["plugins.TestcordHelper.topBarButtonIconColor"] = ["plugins.TestcordHelper.topBarButtonIconColor"];
const TESTCORD_HEADER_BAR_ICON_COLOR_SETTING: ["plugins.TestcordHelper.headerBarButtonIconColor"] = ["plugins.TestcordHelper.headerBarButtonIconColor"];

export interface HeaderBarButtonProps {
    /** The icon component to render inside the button */
    icon: ComponentType<any>;
    /** Tooltip text shown on hover. Pass null to disable tooltip */
    tooltip: ReactNode;
    /** Called when the button is clicked */
    onClick?: MouseEventHandler<HTMLDivElement>;
    /** Called when the button is right-clicked */
    onContextMenu?: MouseEventHandler<HTMLDivElement>;
    /** Additional CSS class names */
    className?: string;
    /** Additional inline styles */
    style?: CSSProperties;
    /** Size of the icon in pixels */
    iconSize?: number;
    /** Tooltip position relative to the button */
    position?: "top" | "bottom" | "left" | "right";
    /** Whether the button appears in a selected/active state */
    selected?: boolean;
    /** Aria label for accessibility */
    "aria-label"?: string;
}

export interface ChannelToolbarButtonProps extends HeaderBarButtonProps {
    /** CSS class name for the icon element */
    iconClassName?: string;
    /** Tooltip position relative to the button */
    position?: "top" | "bottom" | "left" | "right";
    /** Whether the button appears in a selected/active state */
    selected?: boolean;
    /** Whether the button is disabled */
    disabled?: boolean;
    /** Whether to show a notification badge */
    showBadge?: boolean;
    /** Position of the notification badge */
    badgePosition?: "top" | "bottom";
}

export type HeaderBarButtonFactory = () => JSX.Element | null;

export interface HeaderBarButtonData {
    /** Function that renders the button component */
    render: HeaderBarButtonFactory;
    /** Icon component used for settings UI display */
    icon: ComponentType<any>;
    /** Higher priority buttons appear further right. Default: 0 */
    priority?: number;
    /** Where to render the button. Default: "headerbar" */
    location?: "headerbar" | "channeltoolbar";
}

interface ButtonEntry {
    render: HeaderBarButtonFactory;
    priority: number;
}

/**
 * Button component for the top header bar (title bar area).
 *
 * @example
 * <HeaderBarButton
 *     icon={MyIcon}
 *     tooltip="My Button"
 *     onClick={() => console.log("clicked")}
 * />
 */
export function HeaderBarButton(props: HeaderBarButtonProps & { ref?: React.RefObject<any>; }) {
    useSettings(TESTCORD_TOP_BAR_ICON_COLOR_SETTING);
    const iconColor = getTestcordIconColor("topBarButtonIconColor");
    const {
        icon: Icon,
        tooltip,
        onClick,
        onContextMenu,
        className,
        style,
        iconSize = 18,
        position = "bottom",
        selected,
        ref,
        "aria-label": ariaLabel,
    } = props;

    const label = ariaLabel ?? (typeof tooltip === "string" ? tooltip : undefined);
    const buttonStyle: CSSProperties & Record<"--vc-plugin-icon-color", string | undefined> = {
        ...style,
        "--vc-plugin-icon-color": iconColor,
        width: Math.max(iconSize, 24),
        height: Math.max(iconSize, 24),
        boxSizing: "content-box",
        justifyContent: "center"
    };

    return (
        <Tooltip key={String(tooltip)} text={tooltip ?? ""} position={position} shouldShow={tooltip != null}>
            {({ onMouseEnter, onMouseLeave }) => (
                <Clickable
                    {...{ innerRef: ref } as any}
                    className={classes(HeaderBarClasses.clickable, "vc-plugin-icon-button", className)}
                    style={buttonStyle}
                    onClick={event => {
                        onClick?.(event);
                        headerBarListeners.forEach(listener => listener());
                    }}
                    onContextMenu={event => {
                        onContextMenu?.(event);
                        headerBarListeners.forEach(listener => listener());
                    }}
                    onMouseEnter={onMouseEnter}
                    onMouseLeave={onMouseLeave}
                    role="button"
                    tabIndex={0}
                    aria-label={label}
                    aria-expanded={selected}
                >
                    <Icon size="custom" width={iconSize} height={iconSize} color="currentColor" />
                </Clickable>
            )}
        </Tooltip>
    );
}

/**
 * Button component for the channel toolbar (below the search bar).
 * Automatically handles selected state styling.
 *
 * @example
 * <ChannelToolbarButton
 *     icon={MyIcon}
 *     tooltip={isOpen ? null : "My Button"}
 *     onClick={() => setOpen(v => !v)}
 *     selected={isOpen}
 * />
 */
export function ChannelToolbarButton(props: ChannelToolbarButtonProps) {
    useSettings(TESTCORD_HEADER_BAR_ICON_COLOR_SETTING);
    const iconColor = getTestcordIconColor("headerBarButtonIconColor");
    const wrapperStyle: CSSProperties & Record<"--vc-plugin-icon-color", string | undefined> = {
        "--vc-plugin-icon-color": iconColor
    };

    const handleClick: MouseEventHandler<HTMLDivElement> = event => {
        props.onClick?.(event);
        channelToolbarListeners.forEach(listener => listener());
    };

    const handleContextMenu: MouseEventHandler<HTMLDivElement> = event => {
        props.onContextMenu?.(event);
        channelToolbarListeners.forEach(listener => listener());
    };

    const hasWrapped = Boolean((HeaderBarIcon as any)?.$$vencordGetWrappedComponent?.());

    return (
        <span className="vc-plugin-icon-button" style={wrapperStyle}>
            {hasWrapped ? (
                <HeaderBarIcon
                    key={String(props.tooltip)}
                    {...props}
                    className={classes("vc-plugin-icon-button", props.className)}
                    iconClassName={classes("vc-plugin-icon-button", props.iconClassName)}
                    onClick={handleClick}
                    onContextMenu={handleContextMenu}
                />
            ) : (
                <Tooltip text={props.tooltip} position={props.position ?? "bottom"}>
                    {tooltipProps => (
                        <Clickable
                            {...tooltipProps}
                            className={classes(
                                ToolbarClasses.iconWrapper ?? "iconWrapper__9293f",
                                ToolbarClasses.clickable ?? "clickable__9293f",
                                "vc-plugin-icon-button",
                                props.className,
                                props.selected && (HeaderBarClasses.selected ?? "selected__9293f"),
                                props.disabled && "disabled"
                            )}
                            onClick={props.disabled ? undefined : handleClick}
                            onContextMenu={props.disabled ? undefined : handleContextMenu}
                            role="button"
                            aria-label={props["aria-label"] ?? (typeof props.tooltip === "string" ? props.tooltip : undefined)}
                            tabIndex={props.disabled ? -1 : 0}
                        >
                            {props.icon && (
                                <props.icon
                                    className={classes("icon__9293f", props.iconClassName)}
                                    width={props.iconSize ?? 24}
                                    height={props.iconSize ?? 24}
                                    aria-hidden="true"
                                />
                            )}
                        </Clickable>
                    )}
                </Tooltip>
            )}
        </span>
    );
}

const headerBarButtons = new Map<string, ButtonEntry>();
const channelToolbarButtons = new Map<string, ButtonEntry>();

const headerBarListeners = new Set<() => void>();
const channelToolbarListeners = new Set<() => void>();

/**
 * Adds a button to the header bar (title bar area).
 *
 * @param id - Unique identifier for the button (e.g., "my-plugin-button")
 * @param render - Function that returns the button JSX
 * @param priority - Higher values appear further right. Default: 0
 *
 * @example
 * addHeaderBarButton("my-button", () => (
 *     <HeaderBarButton
 *         icon={MyIcon}
 *         tooltip="My Button"
 *         onClick={handleClick}
 *     />
 * ));
 */
export function addHeaderBarButton(id: string, render: HeaderBarButtonFactory, priority = 0) {
    headerBarButtons.set(id, { render, priority });
    headerBarListeners.forEach(listener => listener());
}

/**
 * Removes a button from the header bar.
 *
 * @param id - The identifier used when adding the button
 */
export function removeHeaderBarButton(id: string) {
    headerBarButtons.delete(id);
    headerBarListeners.forEach(listener => listener());
}

/**
 * Adds a button to the channel toolbar (below the search bar, next to pins/members).
 *
 * @param id - Unique identifier for the button (e.g., "my-plugin-toolbar")
 * @param render - Function that returns the button JSX
 * @param priority - Higher values appear further right. Default: 0
 *
 * @example
 * addChannelToolbarButton("my-toolbar", () => (
 *     <ChannelToolbarButton
 *         icon={MyIcon}
 *         tooltip="My Button"
 *         onClick={handleClick}
 *     />
 * ));
 */
export function addChannelToolbarButton(id: string, render: HeaderBarButtonFactory, priority = 0) {
    channelToolbarButtons.set(id, { render, priority });
    channelToolbarListeners.forEach(listener => listener());
}

/**
 * Removes a button from the channel toolbar.
 *
 * @param id - The identifier used when adding the button
 */
export function removeChannelToolbarButton(id: string) {
    channelToolbarButtons.delete(id);
    channelToolbarListeners.forEach(listener => listener());
}

let cachedHeaderBarButtons: { id: string; render: HeaderBarButtonFactory; }[] | null = null;
let cachedChannelToolbarButtons: { id: string; render: HeaderBarButtonFactory; }[] | null = null;

function getSortedHeaderBarButtons() {
    if (cachedHeaderBarButtons && cachedHeaderBarButtons.length === headerBarButtons.size) return cachedHeaderBarButtons;
    cachedHeaderBarButtons = Array.from(headerBarButtons)
        .sort(([, a], [, b]) => a.priority - b.priority)
        .map(([id, { render }]) => ({ id, render }));
    return cachedHeaderBarButtons;
}

function getSortedChannelToolbarButtons() {
    if (cachedChannelToolbarButtons && cachedChannelToolbarButtons.length === channelToolbarButtons.size) return cachedChannelToolbarButtons;
    cachedChannelToolbarButtons = Array.from(channelToolbarButtons)
        .sort(([, a], [, b]) => a.priority - b.priority)
        .map(([id, { render }]) => ({ id, render }));
    return cachedChannelToolbarButtons;
}

function HeaderBarButtons() {
    const [, forceUpdate] = useState(0);

    useEffect(() => {
        const listener = () => { cachedHeaderBarButtons = null; forceUpdate(n => n + 1); };
        headerBarListeners.add(listener);
        return () => { headerBarListeners.delete(listener); };
    }, []);

    return getSortedHeaderBarButtons().map(({ id, render: Button }) => (
        <ErrorBoundary noop key={id} onError={e => logger.error(`Failed to render header bar button: ${id}`, e.error)}>
            <Button />
        </ErrorBoundary>
    ));
}

function ChannelToolbarButtons() {
    const [, forceUpdate] = useState(0);

    useEffect(() => {
        const listener = () => { cachedChannelToolbarButtons = null; forceUpdate(n => n + 1); };
        channelToolbarListeners.add(listener);
        return () => { channelToolbarListeners.delete(listener); };
    }, []);

    return getSortedChannelToolbarButtons().map(({ id, render: Button }) => (
        <ErrorBoundary noop key={id} onError={e => logger.error(`Failed to render channel toolbar button: ${id}`, e.error)}>
            <Button />
        </ErrorBoundary>
    ));
}

/** @internal Injected by HeaderBarAPI patch (do NOT call directly) */
export function _addHeaderBarButtons() {
    return [<HeaderBarButtons key="vc-header-bar-buttons" />];
}

/** @internal Injected by HeaderBarAPI patch (do NOT call directly) */
export function _addChannelToolbarButtons(toolbar: ReactNode[]) {
    toolbar.push(<ChannelToolbarButtons key="vc-channel-toolbar-buttons" />);
}

// ══════════════════════════════════════════════════════════════════
// STEALTH MODE (Nightcord compat) — exposed for plugins that hide UI
// ══════════════════════════════════════════════════════════════════

let _stealthActive = false;
try { _stealthActive = localStorage.getItem("Nightcord_stealthMode") === "1"; } catch { }

const stealthListeners = new Set<() => void>();

export function isStealthModeEnabled(): boolean {
    return _stealthActive;
}

function persistStealth(v: boolean) {
    try { v ? localStorage.setItem("Nightcord_stealthMode", "1") : localStorage.removeItem("Nightcord_stealthMode"); } catch { }
}

const NON_REACT_SELECTORS = [
    "#nightcord-titlebar-btn",
    "#nightcord-titlebar-link-style",
    ".nai-nav-item",
];

function hideNonReactElements(hide: boolean) {
    for (const sel of NON_REACT_SELECTORS) {
        try {
            document.querySelectorAll(sel).forEach(el => {
                (el as HTMLElement).style.display = hide ? "none" : "";
            });
        } catch { }
    }
}

export function syncStealthBodyClass() {
    try { if (_stealthActive) document.body?.classList.add("nightcord-stealth"); else document.body?.classList.remove("nightcord-stealth"); } catch { }
    hideNonReactElements(_stealthActive);
}

export function _notifyStealthChange() {
    stealthListeners.forEach(fn => fn());
    try { window.dispatchEvent(new Event("nightcord-stealth-change")); } catch { }
}

export function toggleStealthMode() {
    _stealthActive = !_stealthActive;
    persistStealth(_stealthActive);
    hideNonReactElements(_stealthActive);
    _notifyStealthChange();
    try { if (_stealthActive) document.body?.classList.add("nightcord-stealth"); else document.body?.classList.remove("nightcord-stealth"); } catch { }
    return _stealthActive;
}

export function addStealthListener(fn: () => void) { stealthListeners.add(fn); }
export function removeStealthListener(fn: () => void) { stealthListeners.delete(fn); }
