tab-active {\n    color: var(--pt-accent-contrast) !important;\n    background: var(--pt-accent);\n}\n\n.vc-pinterest-tool-media-tab svg { width: 13px; height: 13px; }\n\n.vc-pinterest-tool-tab-count {\n    min-width: 16px;\n    padding: 0 4px;\n    border-radius: 5px;\n    background: color-mix(in srgb, currentColor 18%, transparent);\n    font-size: 10.5px;\n    line-height: 16px;\n    text-align: center;\n}\n\n/* Appearance popover */\n.vc-pinterest-tool-personalize {\n    position: relative;\n    z-index: 90;\n    margin-inline-start: auto;\n}\n\n.vc-pinterest-tool-personalize summary {\n    width: 30px;\n    height: 30px;\n    display: grid;\n    place-items: center;\n    border-radius: 8px;\n    color: var(--pt-muted);\n    list-style: none;\n    cursor: pointer;\n}\n\n.vc-pinterest-tool-personalize summary::-webkit-details-marker { display: none; }\n\n.vc-pinterest-tool-personalize[open] summary,\n.vc-pinterest-tool-personalize summary:hover {\n    color: var(--pt-text);\n    background: var(--pt-hover);\n}\n\n.vc-pinterest-tool-personalize-panel {\n    position: absolute;\n    top: calc(100% + 6px);\n    inset-inline-end: 0;\n    min-width: 260px;\n    padding: 10px;\n    display: flex;\n    flex-direction: column;\n    align-items: stretch;\n    gap: 8px;\n    border: 1px solid var(--pt-border);\n    border-radius: 12px;\n    background: var(--pt-popover);\n    color: var(--pt-popover-text);\n    box-shadow: 0 14px 36px rgba(0, 0, 0, .3);\n}\n\n.vc-pinterest-tool-appearance-toggle {\n    height: 28px;\n    padding: 0 10px;\n    border: 0;\n    border-radius: 8px;\n    display: inline-flex;\n    align-items: center;\n    gap: 6px;\n    background: var(--pt-raised);\n    color: var(--pt-text);\n    font-size: 12px;\n    font-weight: 650;\n    cursor: pointer;\n}\n\n.vc-pinterest-tool-appearance-toggle:hover { background: var(--pt-hover); }\n\n/* Search row */\n.vc-pinterest-tool-search-row {\n    display: flex;\n    align-items: center;\n    gap: 6px;\n}\n\n.