(window.VencordStyles ??= new Map()).set("src/plugins/_api/messagePopover.css", {
    name: "src/plugins/_api/messagePopover.css",
    source: "/* Keep the hover toolbar above neighbouring messages.\n   The class names are filled in at runtime. Matching [class*=\"message_\"] instead put this\n   rule in the browser's universal selector bucket, so it was retested against every element\n   on every hover change and every message list mutation.\n\n   The toolbar is absolutely positioned inside the message and deliberately overflows it, so\n   it has to clear the rows above and below it. Message rows are `position: relative` with\n   `z-index: auto`, and an `auto` z-index on a positioned element still paints in DOM order,\n   so a later row paints over an earlier one no matter what the earlier one is hovered with.\n   Raising the row alone was therefore not enough: it needed the sibling rows to be\n   unpositioned at the same time, which nothing guaranteed.\n\n   Raising the toolbar itself is what actually fixes it, because it is the thing that\n   overflows. The value only has to beat the message layer, and 2 is enough for that while\n   staying far below Discord's own overlays (the jump-to-present pill sits at 3, popovers and\n   modals in the thousands), so the toolbar can never end up above a real overlay. */\n[--messageListItem]:hover,\n[--message]:hover {\n    position: relative;\n    z-index: 1;\n}\n\n[--messageListItem]:hover .vc-message-popover,\n[--message]:hover .vc-message-popover {\n    z-index: 2;\n}\n",
    classNames: {},
    enabled: false,
    compiled: "",
});

export default "src/plugins/_api/messagePopover.css";
