import { ErrorCard } from "@components/ErrorCard";
import { UpdateLogger } from "@utils/updater";
import { ConfirmModal,openModal, Parser } from "@webpack/common";

function getErrorMessage(e: any) {
    if (e?.message) {
        if (e.cmd) {
            const extra = e.stderr || e.message;
            return `An error occurred while running \`${e.cmd}\`:\n${extra}`;
        }
        return e.message;
    }

    if (e?.code && e?.cmd) {
        const { code, path, cmd, stderr } = e;

        if (code === "ENOENT")
            return `Command \`${path}\` not found.\nPlease install it and try again.`;

        const extra = stderr || `Code \`${code}\`. See the console for more info.`;

        return `An error occurred while running \`${cmd}\`:\n${extra}`;
    }

    if (typeof e === "string")
        return e;

    return "An unknown error occurred.\nPlease try again or see the console for more info.";
}

export function runWithDispatch(dispatch: React.Dispatch<React.SetStateAction<boolean>>, action: () => any, onError?: (e: any) => void) {
    return async () => {
        dispatch(true);

        try {
            await action();
        } catch (e: any) {
            UpdateLogger.error(e);
            onError?.(e);

            const err = getErrorMessage(e);

            openModal(props => (
                <ConfirmModal
                    {...props}
                    title="Oops!"
                    confirmText="OK"
                    variant="primary"
                >
                    <ErrorCard>
                        {err.split("\n").map((line, idx) =>
                            <div key={idx}>{Parser.parse(line)}</div>
                        )}
                    </ErrorCard>
                </ConfirmModal>
            ));
        } finally {
            dispatch(false);
        }
    };
}
