/* stylelint-disable rule-empty-line-before */
/* stylelint-disable property-no-vendor-prefix */

@keyframes smyn-animation {
    0% {
        background-position: 0;
    }

    100% {
        background-position: 100px;
    }
}

.smyn-gradient {
    position: relative;
    z-index: 0;

    /* Layout + style containment only (never paint: the glow ::after must
       stay visible outside the bounds). Narrows style recalc when names
       update without changing rendering. */
    contain: layout style;
}

.smyn-gradient::after {
    background-clip: text;
    content: attr(data-text) / "";
    inset: 0;
    position: absolute;
    filter: blur(4px);
    opacity: 0;
    text-indent: 0;
    transition: opacity .1s ease-in-out;
    text-wrap-style: balance;
    z-index: -1;
}

.smyn-gradient-unset-bg::after {
    background: unset;
    -webkit-text-fill-color: currentcolor;
}

.smyn-gradient-inherit-bg::after {
    background: inherit;
    -webkit-text-fill-color: transparent;
}

.smyn-gradient-hovered::after {
    opacity: .7;
    transition: opacity .1s ease-in-out;
}

.smyn-modal-footer-container button {
    width: 100%;
}

.smyn-reset-button {
    margin-top: 8px;
    font-size: 14px;
    font-weight: 500;
}


.smyn-native-gradient [data-username-with-effects] {
    background-image: linear-gradient(90deg, var(--custom-gradient-color-1, var(--custom-display-name-styles-main-color, currentColor)), var(--custom-gradient-color-2, var(--custom-display-name-styles-main-color, currentColor))) !important;
    background-size: 100% 100% !important;
    -webkit-background-clip: text !important;
    background-clip: text !important;
    -webkit-text-fill-color: transparent !important;
}

.smyn-native-gradient-animated [data-username-with-effects],
.smyn-native-gradient-animated > [data-username-with-effects],
:where(.smyn-native-gradient-glow-overflow) .smyn-native-gradient-glow > [data-username-with-effects] {
    background-image: linear-gradient(to right, var(--custom-gradient-color-1, var(--custom-display-name-styles-main-color, currentColor)), var(--custom-gradient-color-2, var(--custom-display-name-styles-main-color, currentColor)), var(--custom-gradient-color-1, var(--custom-display-name-styles-main-color, currentColor))) !important;
    background-size: 100px auto !important;
    animation: smyn-animation var(--smyn-gradient-duration, 1.5s) linear infinite;
    -webkit-background-clip: text !important;
    background-clip: text !important;
    -webkit-text-fill-color: transparent !important;
}


.smyn-offscreen.smyn-gradient,
.smyn-offscreen .smyn-gradient,
.smyn-offscreen [data-username-with-effects],
.smyn-offscreen .smyn-name {
    animation-play-state: paused !important;
}


@media (prefers-reduced-motion: reduce) {

    .smyn-native-gradient-animated > [data-username-with-effects],
    :where(.smyn-native-gradient-glow-overflow) .smyn-native-gradient-glow > [data-username-with-effects] {
        animation: none;
    }

    .smyn-gradient::after,
    .smyn-native-gradient-glow > [data-username-with-effects]::after {
        transition: none;
    }
}

.smyn-native-gradient-glow > [data-username-with-effects]::after {
    background: inherit;
    background-clip: text;
    content: attr(data-username-with-effects) / "";
    filter: blur(4px);
    inset: 0;
    opacity: 0;
    position: absolute;
    text-indent: 0;
    transition: opacity .1s ease-in-out;
    -webkit-text-fill-color: transparent;
    z-index: -1;
}

.smyn-native-gradient-glow-active > [data-username-with-effects],
.smyn-native-gradient-glow-overflow,
.smyn-native-gradient-glow-overflow > .smyn-name-group,
.smyn-native-gradient-glow-overflow > .smyn-name-group > .smyn-name,
.smyn-native-gradient-glow-overflow :where([class^="text_"],
    [class*=" text_"],
    [class^="username_"],
    [class*=" username_"]) {
    overflow: visible;
}

.smyn-native-gradient-glow-active > [data-username-with-effects]::after,
:where(.smyn-native-gradient-glow-overflow) .smyn-native-gradient-glow > [data-username-with-effects]::after {
    opacity: .7 !important;
    transition: opacity .1s ease-in-out;
}

.smyn-native-effect.smyn-native-message-effect {
    display: inline;
}

.smyn-native-gummy-animated > [data-username-with-effects] {
    --smyn-gummy-inline-headroom: .12em;

    margin-inline: calc(var(--smyn-gummy-inline-headroom) * -1);
    padding-inline: var(--smyn-gummy-inline-headroom);
    text-overflow: clip;
}

.smyn-container:hover {
    text-decoration-color: var(--smyn-underline-color, currentcolor);
    text-decoration-line: underline;
    text-decoration-style: initial;
    text-decoration-thickness: initial;
}

.smyn-container:hover .smyn-native-effect > [data-username-with-effects] {
    text-decoration-color: var(--smyn-underline-color, currentcolor);
    text-decoration-line: underline;
    text-decoration-style: initial;
    text-decoration-thickness: initial;
}

.smyn-container:hover .smyn-native-pop > [data-username-with-effects],
.smyn-container:hover .smyn-native-gummy > [data-username-with-effects] {
    text-decoration: none;
}

.smyn-container:hover .smyn-native-pop > [data-username-with-effects]::before {
    text-decoration-color: var(--smyn-underline-color, currentcolor);
    text-decoration-line: underline;
    text-decoration-style: initial;
    text-decoration-thickness: initial;
    text-underline-offset: .08em;
}

.smyn-container:hover .smyn-native-gummy > [data-username-with-effects] {
    position: relative;
}

.smyn-container:hover .smyn-native-gummy > [data-username-with-effects]::before {
    color: transparent;
    content: attr(data-username-with-effects) / "";
    inset: var(--custom-gummy-squish-headroom, 0) 0 0;
    pointer-events: none;
    position: absolute;
    text-decoration-color: var(--smyn-underline-color, currentcolor);
    text-decoration-line: underline;
    text-decoration-style: initial;
    text-decoration-thickness: initial;
    white-space: var(--custom-display-name-styles-wrap);
}